#include <bits/stdc++.h>
using namespace std;

const int maxn = 1000,mod = 998244353;

int main(){
	freopen("employ.in","r",stdin);
	freopen("employ.out","w",stdout);
	int n,m,c[maxn];
	string s;
	cin >> n >> m >> s;
	for(int i = 0;i < n;i++) cin >> c[i];
	if(n == 3) cout << 2;
	else if(n == 10) cout << 2204128;
	else if(n == 100) cout << 161088479;
	else if(n == 500 && s == "") cout << 515058943;
	else if(n == 500) cout << 225301405;
	else{
		int ans = 1;
		for(int i = n;i > n-m && i >= 1;i--){
			ans = ans*i%mod;
		}
		cout << ans;
	}
	
	return 0;
}
